const packageCountries = (() => {
  if (!packageCountriesModule || typeof packageCountriesModule !== 'object') return null;
  if (packageCountriesModule.countries && typeof packageCountriesModule.countries === 'object') return packageCountriesModule.countries;
  const moduleDefault = Reflect.get(packageCountriesModule, 'default');
  if (moduleDefault && typeof moduleDefault === 'object') {
    if (moduleDefault.countries && typeof moduleDefault.countries === 'object') {
      return moduleDefault.countries;
    }
    return moduleDefault;
  }
  return packageCountriesModule;
})();

const AUTOPLAY_STORAGE_KEY = 'playhub_autoplay_enabled';
const AUTOPLAY_NEXT_STORAGE_KEY = 'playhub_autoplay_next_slug';
