const loadLiveKit = () => import('livekit-client');
const emojiPickerPlacementFor = (trigger, pickerHeight = 390) => {
  const rect = trigger?.getBoundingClientRect?.();
  if (!rect || typeof window === 'undefined') return 'bottom';
  const viewportHeight = window.innerHeight || document.documentElement.clientHeight || 0;
  const spaceBelow = viewportHeight - rect.bottom;
  const spaceAbove = rect.top;
  return spaceBelow < pickerHeight && spaceAbove > spaceBelow ? 'top' : 'bottom';
};

const escapeGalleryHtml = (value = '') => String(value)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;')
  .replace(/'/g, '&#039;');

function readAutoplayPreference(user) {
  const userValue = user?.settings?.preferences?.autoplay;
  if (typeof userValue === 'boolean') return userValue;
  if (user) return true;
  try {
    const stored = localStorage.getItem(AUTOPLAY_STORAGE_KEY);
    return stored === null ? true : stored === 'true';
  } catch (_) {
    return true;
  }
}

function writeGuestAutoplayPreference(enabled) {
  try {
    localStorage.setItem(AUTOPLAY_STORAGE_KEY, enabled ? 'true' : 'false');
  } catch (_) {}
}

const safeGalleryGroup = (value = 'media') => String(value).replace(/[^a-zA-Z0-9_-]/g, '-');
const GlobalGalleryContext = React.createContext(() => {});

const normalizeGalleryItems = (items = []) => items
  .filter((item) => item?.src)
  .map((item) => ({
    src: item.src,
    thumb: item.thumb || item.src,
    title: item.title || websiteName(),
    description: String(item.description || '').trim(),
    alt: item.alt || item.title || `${websiteName()} media`,
    downloadUrl: item.downloadUrl || item.src,
    image_candidates: item.image_candidates || [],
  }));

function GlobalGalleryProvider({ children }) {
  const overlayRef = useRef(null);
  const swipeStartRef = useRef(null);
  const [gallery, setGallery] = useState(null);
  const [zoom, setZoom] = useState(1);
  const [rotation, setRotation] = useState(0);
  const [resolvedImage, setResolvedImage] = useState({ src: '', url: '' });

  const openGallery = useCallback((items = [], index = 0) => {
    const dynamicItems = normalizeGalleryItems(items);
    if (!dynamicItems.length) return;
    setGallery({ items: dynamicItems, index: Math.max(0, Math.min(index, dynamicItems.length - 1)) });
  }, []);
  const closeGallery = useCallback(() => {
    if (document.fullscreenElement === overlayRef.current) document.exitFullscreen?.().catch?.(() => {});
    setGallery(null);
  }, []);
  const moveGallery = useCallback((direction) => {
    setGallery((current) => current ? { ...current, index: (current.index + direction + current.items.length) % current.items.length } : null);
  }, []);

  useEffect(() => {
    if (!gallery) return undefined;
    setZoom(1);
    setRotation(0);
    const previousOverflow = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    window.requestAnimationFrame(() => overlayRef.current?.focus());
    const handleKeyDown = (event) => {
      if (event.key === 'Escape') closeGallery();
      else if (event.key === 'ArrowLeft') moveGallery(-1);
      else if (event.key === 'ArrowRight') moveGallery(1);
      else if (event.key === '+' || event.key === '=') setZoom((value) => Math.min(3, value + .25));
      else if (event.key === '-') setZoom((value) => Math.max(1, value - .25));
      else if (event.key.toLowerCase() === 'r') setRotation((value) => value + 90);
      else return;
      event.preventDefault();
    };
    const closeOnNavigation = () => closeGallery();
    document.addEventListener('keydown', handleKeyDown);
    window.addEventListener('playhub:navigation', closeOnNavigation);
    return () => {
      document.body.style.overflow = previousOverflow;
      document.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('playhub:navigation', closeOnNavigation);
    };
  }, [Boolean(gallery), closeGallery, moveGallery]);

  useEffect(() => {
    setZoom(1);
    setRotation(0);
  }, [gallery?.index]);

  const current = gallery?.items[gallery.index];
  const currentImageUrl = current && resolvedImage.src === current.src ? resolvedImage.url || current.src : current?.src;
  const shareCurrent = async () => {
    if (!current) return;
    try {
      if (navigator.share) await navigator.share({ title: current.title, text: current.description, url: currentImageUrl });
      else await navigator.clipboard?.writeText(currentImageUrl);
    } catch (error) {
      if (error?.name !== 'AbortError') window.open(currentImageUrl, '_blank', 'noopener,noreferrer');
    }
  };
  const toggleFullscreen = () => {
    if (document.fullscreenElement) document.exitFullscreen?.().catch?.(() => {});
    else overlayRef.current?.requestFullscreen?.().catch?.(() => {});
  };
  const finishSwipe = (event) => {
    if (swipeStartRef.current === null || event.pointerType !== 'touch') return;
    const distance = event.clientX - swipeStartRef.current;
    swipeStartRef.current = null;
    if (Math.abs(distance) >= 45) moveGallery(distance > 0 ? -1 : 1);
  };

  return <GlobalGalleryContext.Provider value={openGallery}>
    {children}
    {current && createPortal(<div ref={overlayRef} className="playhub-gallery-overlay" role="dialog" aria-modal="true" aria-label={current.title} tabIndex={-1} onMouseDown={(event) => { if (event.target === event.currentTarget) closeGallery(); }} onPointerDown={(event) => { if (event.pointerType === 'touch') swipeStartRef.current = event.clientX; }} onPointerUp={finishSwipe} onPointerCancel={() => { swipeStartRef.current = null; }}>
      <div className="playhub-gallery-toolbar">
        <span data-i18n-skip>{gallery.index + 1} / {gallery.items.length}</span>
        <button type="button" onClick={() => setZoom((value) => Math.min(3, value + .25))} aria-label="Zoom in" title="Zoom in"><Icon name="zoomIn" size={20}/></button>
        <button type="button" onClick={() => setZoom((value) => Math.max(1, value - .25))} disabled={zoom <= 1} aria-label="Zoom out" title="Zoom out"><Icon name="zoomOut" size={20}/></button>
        <button type="button" onClick={() => setRotation((value) => value + 90)} aria-label="Rotate image" title="Rotate"><Icon name="rotate" size={20}/></button>
        <button type="button" onClick={toggleFullscreen} aria-label="Toggle fullscreen" title="Fullscreen"><Icon name="expand" size={20}/></button>
        <button type="button" onClick={shareCurrent} aria-label="Share image" title="Share"><Icon name="share" size={20}/></button>
        <a href={currentImageUrl || current.downloadUrl} download target="_blank" rel="noopener" aria-label="Download image" title="Download"><Icon name="download" size={20}/></a>
        <button type="button" onClick={closeGallery} aria-label="Close gallery" title="Close"><Icon name="close" size={20}/></button>
      </div>
      {gallery.items.length > 1 && <button type="button" className="playhub-gallery-nav previous" onClick={() => moveGallery(-1)} aria-label="Previous image"><Icon name="chevronLeft" size={28}/></button>}
      <div className="playhub-gallery-stage"><AttachmentImage attachment={{ url: current.src, image_candidates: current.image_candidates }} onResolved={(url) => setResolvedImage({ src: current.src, url })} alt={current.alt} draggable="false" onDoubleClick={() => setZoom((value) => value > 1 ? 1 : 2)} style={{ transform: `scale(${zoom}) rotate(${rotation}deg)` }} /></div>
      {gallery.items.length > 1 && <button type="button" className="playhub-gallery-nav next" onClick={() => moveGallery(1)} aria-label="Next image"><Icon name="chevronRight" size={28}/></button>}
      <div className="playhub-gallery-footer">
        <div className="playhub-gallery-caption"><strong>{current.title}</strong>{current.description && <p>{current.description}</p>}</div>
        {gallery.items.length > 1 && <div className="playhub-gallery-thumbnails">{gallery.items.map((item, index) => <button type="button" key={`${item.src}-${index}`} className={index === gallery.index ? 'active' : ''} onClick={() => setGallery((value) => ({ ...value, index }))} aria-label={`Open image ${index + 1}`}><AttachmentImage attachment={{ url: item.thumb, image_candidates: item.image_candidates }} alt="" /></button>)}</div>}
      </div>
    </div>, document.body)}
  </GlobalGalleryContext.Provider>;
}

function GalleryImage({ src, thumb, title, description, itemClassName = 'playhub-gallery-item', galleryItems, galleryIndex = 0, children }) {
  const openGallery = React.useContext(GlobalGalleryContext);
  const items = galleryItems?.length ? galleryItems : [{ src, thumb, title, description }];
  if (!src) return <div className={itemClassName}>{children}</div>;

  const handleOpen = (event) => {
    event.preventDefault();
    event.stopPropagation();
    openGallery(items, galleryIndex);
  };

  return <div className={itemClassName} onClick={handleOpen} role="presentation">
    {children}
  </div>;
}

let pageRequestSequence = 0;
const pendingPageRequests = new Map();
const pageRequestSubscribers = new Set();
const currentPageRequestKey = () => typeof window === 'undefined' ? '' : `${window.location.pathname}${window.location.search}`;
const notifyPageRequestSubscribers = () => pageRequestSubscribers.forEach((subscriber) => subscriber());
const beginPageRequest = (path) => {
  const id = ++pageRequestSequence;
  pendingPageRequests.set(id, { path, routeKey: currentPageRequestKey() });
  notifyPageRequestSubscribers();
  return id;
};
const finishPageRequest = (id) => {
  if (!id || !pendingPageRequests.delete(id)) return;
  notifyPageRequestSubscribers();
};
const pendingPageRequestCount = (routeKey) => [...pendingPageRequests.values()].filter((request) => request.routeKey === routeKey).length;
const subscribeToPageRequests = (subscriber) => {
  pageRequestSubscribers.add(subscriber);
  return () => pageRequestSubscribers.delete(subscriber);
};

let observedAuthenticationToken;
let websiteAuthenticationEpoch = 0;
const api = {
  token: () => localStorage.getItem('playhub_token') || sessionStorage.getItem('playhub_token'),
  authenticationEpoch: () => {
    const token = api.token();
    if (token !== observedAuthenticationToken) { observedAuthenticationToken = token; websiteAuthenticationEpoch++; }
    return websiteAuthenticationEpoch;
  },
  setToken: (token, remember = true) => {
    localStorage.removeItem('playhub_token');
    sessionStorage.removeItem('playhub_token');
    if (token) (remember ? localStorage : sessionStorage).setItem('playhub_token', token);
    api.authenticationEpoch();
    window.dispatchEvent(new CustomEvent('playhub:auth-changed'));
  },
  async request(path, options = {}) {
    const trackPageLoading = options.trackPageLoading !== false;
    const requestOptions = { ...options };
    delete requestOptions.trackPageLoading;
    const authenticationEpoch = api.authenticationEpoch();
    if (requestOptions.expectedAuthEpoch !== undefined && requestOptions.expectedAuthEpoch !== authenticationEpoch) {
      const error = new Error('Your session changed. Please try again.'); error.code = 'session_changed'; throw error;
    }
    delete requestOptions.expectedAuthEpoch;
    const headers = new Headers(requestOptions.headers || {});
    headers.set('Accept', 'application/json');
    if (!(requestOptions.body instanceof FormData) && !headers.has('Content-Type')) headers.set('Content-Type', 'application/json');
    const interfaceLanguage = localStorage.getItem('playhub_language');
    if (interfaceLanguage && /^[a-z0-9_-]+$/i.test(interfaceLanguage)) headers.set('X-PlayHub-Language', interfaceLanguage);
    // Use the same observed credential as the epoch check, never a second
    // storage read that could belong to an account changed in another tab.
    const token = observedAuthenticationToken;
    if (token) headers.set('Authorization', `Bearer ${token}`);
    const pageRequestId = trackPageLoading ? beginPageRequest(path) : null;

    try {
      const response = await fetch(`/api${path}`, { ...requestOptions, headers });
      const contentType = response.headers.get('content-type') || '';
      const payload = contentType.includes('application/json') ? await response.json() : await response.text();

      if (!response.ok) {
        const validation = payload?.error?.validation || payload?.errors || {};
        const message = payload?.error?.message || payload?.message || Object.values(validation)?.flat()?.[0] || 'Request failed.';
        const error = new Error(message);
        error.status = response.status;
        error.retryAfter = response.headers.get('Retry-After');
        error.payload = payload;
        error.code = payload?.error?.code;
        throw error;
      }

      return payload;
    } finally {
      finishPageRequest(pageRequestId);
    }
  },
};

function PageLoadingBoundary({ children, routeKey, blocking = false, mode = 'instant' }) {
  const [loadingState, setLoadingState] = useState(() => ({ routeKey, phase: 'loading' }));
  const [visibleRouteKey, setVisibleRouteKey] = useState(null);
  const visibleChildrenRef = useRef(children);
  const activeRouteRef = useRef(routeKey);
  const progressMode = mode === 'bar';
  const transitioning = progressMode && visibleRouteKey !== null && visibleRouteKey !== routeKey;

  activeRouteRef.current = routeKey;
  if (!transitioning) visibleChildrenRef.current = children;

  useEffect(() => {
    if (!progressMode) {
      setVisibleRouteKey(routeKey);
      setLoadingState((current) => current.routeKey === routeKey && current.phase === 'ready' ? current : { routeKey, phase: 'ready' });
      return undefined;
    }

    let quietTimer = null;
    let revealTimer = null;
    let maxTimer = null;
    let completing = false;
    let forceCompletion = false;
    let revealed = false;
    const setPhase = (phase) => {
      if (activeRouteRef.current !== routeKey) return;
      setLoadingState((current) => current.routeKey === routeKey && current.phase === phase ? current : { routeKey, phase });
    };

    setPhase('loading');

    const finish = (force = false) => {
      if (revealed) return;
      forceCompletion = forceCompletion || force;
      if (completing) return;
      completing = true;
      setPhase('complete');
      revealTimer = window.setTimeout(() => {
        if (!forceCompletion && (blocking || pendingPageRequestCount(routeKey) > 0)) {
          completing = false;
          setPhase('loading');
          evaluate();
          return;
        }
        revealed = true;
        setVisibleRouteKey(routeKey);
        setPhase('ready');
      }, 180);
    };

    const evaluate = () => {
      window.clearTimeout(quietTimer);
      if (revealed) return;
      if (blocking || pendingPageRequestCount(routeKey) > 0) {
        if (completing && !forceCompletion) {
          completing = false;
          window.clearTimeout(revealTimer);
          setPhase('loading');
        }
        return;
      }
      quietTimer = window.setTimeout(() => finish(false), 160);
    };

    const unsubscribe = subscribeToPageRequests(evaluate);
    evaluate();
    if (!blocking) maxTimer = window.setTimeout(() => finish(true), 12000);

    return () => {
      unsubscribe();
      window.clearTimeout(quietTimer);
      window.clearTimeout(revealTimer);
      window.clearTimeout(maxTimer);
    };
  }, [blocking, progressMode, routeKey]);

  const phase = loadingState.routeKey === routeKey ? loadingState.phase : 'loading';
  const pending = progressMode && phase !== 'ready';
  const holdPrevious = transitioning && pending;
  const displayedRouteKey = holdPrevious ? visibleRouteKey : routeKey;
  const displayedChildren = holdPrevious ? visibleChildrenRef.current : children;
  return <>
    {pending && <div className={`app-loading-bar ${phase === 'complete' ? 'is-complete' : ''}`} role="progressbar" aria-label="Loading page" aria-valuemin="0" aria-valuemax="100" aria-valuenow={phase === 'complete' ? 100 : undefined}><span /></div>}
    <div className={`app-main ${visibleRouteKey === null && pending ? 'is-initial-page-loading' : ''} ${holdPrevious ? 'is-route-transitioning' : ''}`} aria-busy={pending}>
      <div className="app-route-stage is-visible" key={displayedRouteKey}>{displayedChildren}</div>
      {holdPrevious && <div className="app-route-stage is-preloading" key={routeKey} aria-hidden="true" inert="">{children}</div>}
    </div>
  </>;
}

const WebsiteAdsContext = React.createContext([]);

function WebsiteAdSlot({ placement, sequence = 0, className = '' }) {
  const ads = React.useContext(WebsiteAdsContext);
  const containerRef = useRef(null);
  const iframeRef = useRef(null);
  const trackedAdRef = useRef(null);
  const candidates = useMemo(() => ads.filter((ad) => ad.placement === placement && (!sequence || sequence % Math.max(1, Number(ad.every_n_items) || 1) === 0)), [ads, placement, sequence]);
  const ad = candidates.length ? candidates[(sequence ? sequence - 1 : 0) % candidates.length] : null;
  const [dismissed, setDismissed] = useState(false);

  useEffect(() => {
    if (!ad) return;
    try { setDismissed(sessionStorage.getItem(`playhub_ad_dismissed_${ad.id}`) === '1'); } catch (_) { setDismissed(false); }
  }, [ad?.id]);

  useEffect(() => {
    if (!ad || dismissed || !containerRef.current || trackedAdRef.current === ad.id) return undefined;
    const track = () => {
      if (trackedAdRef.current === ad.id) return;
      trackedAdRef.current = ad.id;
      api.request(`/website-ads/${ad.id}/impression`, { method: 'POST', keepalive: true }).catch(() => {});
    };
    if (!('IntersectionObserver' in window)) {
      track();
      return undefined;
    }
    const observer = new IntersectionObserver((entries) => {
      if (entries.some((entry) => entry.isIntersecting && entry.intersectionRatio >= 0.5)) {
        track();
        observer.disconnect();
      }
    }, { threshold: [0.5] });
    observer.observe(containerRef.current);
    return () => observer.disconnect();
  }, [ad?.id, dismissed]);

  const trackClick = useCallback(() => {
    if (ad?.id) api.request(`/website-ads/${ad.id}/click`, { method: 'POST', keepalive: true }).catch(() => {});
  }, [ad?.id]);

  useEffect(() => {
    if (!ad || ad.creative_type !== 'html') return undefined;
    const handleMessage = (event) => {
      if (event.source === iframeRef.current?.contentWindow && event.data?.type === 'playhub:website-ad-click' && Number(event.data?.id) === Number(ad.id)) trackClick();
    };
    window.addEventListener('message', handleMessage);
    return () => window.removeEventListener('message', handleMessage);
  }, [ad?.id, ad?.creative_type, trackClick]);

  if (!ad || dismissed) return null;

  const dismiss = () => {
    try { sessionStorage.setItem(`playhub_ad_dismissed_${ad.id}`, '1'); } catch (_) {}
    setDismissed(true);
  };
  const style = {
    '--website-ad-height': `${Math.max(50, Number(ad.height) || 90)}px`,
    maxWidth: ad.max_width ? `${ad.max_width}px` : undefined,
    backgroundColor: ad.background_color || undefined,
  };
  const linkProps = ad.target_url ? {
    href: ad.target_url,
    target: ad.open_new_tab ? '_blank' : undefined,
    rel: ad.open_new_tab ? 'noopener noreferrer sponsored' : 'sponsored',
    onClick: trackClick,
  } : null;
  let creative;
  if (ad.creative_type === 'html') {
    const relay = `<script>document.addEventListener('click',function(){parent.postMessage({type:'playhub:website-ad-click',id:${Number(ad.id)}},'*')},true);<\/script>`;
    creative = <iframe ref={iframeRef} title={ad.label || 'Sponsored content'} sandbox="allow-scripts allow-forms allow-popups allow-popups-to-escape-sandbox" srcDoc={`${ad.html_content || ''}${relay}`}/>;
  } else if (ad.creative_type === 'image') {
    const image = <img src={ad.image_url} alt={ad.title || ad.label || 'Sponsored content'} loading="lazy"/>;
    creative = linkProps ? <a {...linkProps}>{image}</a> : image;
  } else {
    const text = <span className="website-ad-copy"><strong>{ad.title}</strong>{ad.body && <span>{ad.body}</span>}</span>;
    creative = linkProps ? <a {...linkProps}>{text}</a> : text;
  }

  return <aside ref={containerRef} className={`website-ad-slot website-ad-${ad.display_style || 'card'} website-ad-${placement} ${className}`.trim()} style={style} aria-label={ad.label || 'Sponsored content'}>
    {ad.show_label && <span className="website-ad-label">{ad.label || 'Sponsored'}</span>}
    {creative}
    {ad.dismissible && <button type="button" className="website-ad-dismiss" onClick={dismiss} aria-label="Dismiss ad"><Icon name="close" size={14}/></button>}
  </aside>;
}

function installGoogleAnalytics(settings = {}) {
  const measurementId = settings?.analytics?.googleAnalytics?.enabled ? settings.analytics.googleAnalytics.measurementId : '';
  if (!measurementId || window.__playhubGoogleAnalyticsId === measurementId) return;

  window.__playhubGoogleAnalyticsId = measurementId;
  window.dataLayer = window.dataLayer || [];
  window.gtag = window.gtag || function gtag(){ window.dataLayer.push(arguments); };

  const script = document.createElement('script');
  script.async = true;
  script.src = `https://www.googletagmanager.com/gtag/js?id=${encodeURIComponent(measurementId)}`;
  document.head.appendChild(script);

  const trackPage = () => window.gtag('config', measurementId, { page_path: window.location.pathname + window.location.search });
  window.gtag('js', new Date());
  trackPage();
  window.addEventListener('playhub:navigation', trackPage);
}

const PLAYBACK_QUEUE_KEY = 'playhub_playback_queue_v1';
const WATCH_THEATER_MODE_KEY = 'playhub_watch_theater_mode_v1';
const readWatchTheaterMode = () => {
  try { return localStorage.getItem(WATCH_THEATER_MODE_KEY) === 'true'; } catch (_) { return false; }
};
const readPlaybackQueue = () => {
  try {
    return (JSON.parse(localStorage.getItem(PLAYBACK_QUEUE_KEY) || '[]') || []).filter((item) => item?.slug);
  } catch (_) {
    return [];
  }
};
const writePlaybackQueue = (items) => {
  const unique = [...new Map(items.filter((item) => item?.slug).map((item) => [item.slug, item])).values()].slice(0, 50);
  localStorage.setItem(PLAYBACK_QUEUE_KEY, JSON.stringify(unique));
  window.dispatchEvent(new CustomEvent('playhub:queue-updated', { detail: unique }));
  return unique;
};
const videoQueueSnapshot = (video) => ({
  id: video.id,
  slug: video.slug,
  title: video.title,
  description: video.description,
  thumbnail_url: video.thumbnail_url,
  thumbnail_candidates: video.thumbnail_candidates,
  video_width: video.video_width, video_height: video.video_height,
  fallback_thumbnail_url: video.fallback_thumbnail_url,
  duration: video.duration,
  duration_seconds: video.duration_seconds,
  views_count: video.views_count || 0,
  created_label: video.created_label || 'Queued',
  channel: video.channel,
  theme: video.theme,
  source_type: video.source_type,
  is_short: isShortVideo(video),
});

const persistentVideoSnapshot = (video) => {
  const { description, ...snapshot } = videoQueueSnapshot(video || {});
  return snapshot;
};

const PERSISTENT_PLAYBACK_KEY = 'playhub_persistent_playback_v1';
const PERSISTENT_PLAYBACK_EVENT = 'playhub:persistent-playback';
const PERSISTENT_PLAYBACK_TTL_MS = 7 * 24 * 60 * 60 * 1000;
const PERSISTENT_PLAYER_WIDTH_KEY = 'playhub_persistent_player_width_v1';
const PERSISTENT_PLAYER_POSITION_KEY = 'playhub_persistent_player_position_v1';
const isDesktopPlaybackViewport = () => typeof window !== 'undefined'
  && (window.matchMedia?.('(min-width: 861px)')?.matches ?? window.innerWidth > 860);
let persistentPlaybackSession = null;
try { localStorage.removeItem(PERSISTENT_PLAYBACK_KEY); } catch (_) {}
const clampPersistentPlayerWidth = (value) => Math.max(320, Math.min(720, Math.round(Number(value) || 390)));
const readPersistentPlayerWidth = () => {
  try { return clampPersistentPlayerWidth(localStorage.getItem(PERSISTENT_PLAYER_WIDTH_KEY)); } catch (_) { return 390; }
};
const readPersistentPlayerPosition = () => {
  try {
    const value = JSON.parse(localStorage.getItem(PERSISTENT_PLAYER_POSITION_KEY) || 'null');
    if (Number.isFinite(Number(value?.right)) && Number.isFinite(Number(value?.bottom))) {
      return { right: Math.max(8, Number(value.right)), bottom: Math.max(8, Number(value.bottom)) };
    }
  } catch (_) {}
  return { right: 18, bottom: 18 };
};

const normalizePersistentPlaybackSession = (value) => {
  if (!value?.video?.slug || isShortVideo(value.video)) return null;
  const updatedAt = Number(value.updated_at || 0);
  if (!updatedAt || Date.now() - updatedAt > PERSISTENT_PLAYBACK_TTL_MS) return null;
  const duration = Math.max(0, Number(value.duration || value.video.duration_seconds || 0) || 0);
  const currentTime = Math.max(0, Math.min(Number(value.current_time || 0) || 0, duration > 0 ? duration : Number.MAX_SAFE_INTEGER));
  const compactItems = (items) => [...new Map((Array.isArray(items) ? items : []).filter((item) => item?.slug && !isShortVideo(item)).map((item) => [item.slug, persistentVideoSnapshot(item)])).values()].slice(0, 25);
  return {
    version: 1,
    account_id: value.account_id ? Number(value.account_id) : null,
    video: persistentVideoSnapshot(value.video),
    queue: compactItems(value.queue).filter((item) => item.slug !== value.video.slug),
    history: compactItems(value.history).filter((item) => item.slug !== value.video.slug),
    current_time: currentTime,
    duration,
    volume: Math.max(0, Math.min(1, Number(value.volume ?? 1) || 0)),
    muted: Boolean(value.muted),
    playing: Boolean(value.playing),
    updated_at: updatedAt,
  };
};

const readPersistentPlaybackSession = () => {
  persistentPlaybackSession = normalizePersistentPlaybackSession(persistentPlaybackSession);
  return persistentPlaybackSession;
};

const writePersistentPlaybackSession = (value, runtimeVideo = null, notify = true) => {
  // Starting a new session uses the desktop control; an existing session must
  // survive resizing into the compact layout without losing playback.
  if (!isDesktopPlaybackViewport() && !persistentPlaybackSession) return null;
  try {
    const session = normalizePersistentPlaybackSession({ ...value, updated_at: Date.now() });
    if (!session) {
      persistentPlaybackSession = null;
      if (notify) window.dispatchEvent(new CustomEvent(PERSISTENT_PLAYBACK_EVENT, { detail: { session: null, video: null } }));
      return null;
    }
    persistentPlaybackSession = session;
    if (notify) window.dispatchEvent(new CustomEvent(PERSISTENT_PLAYBACK_EVENT, { detail: { session, video: runtimeVideo } }));
    return session;
  } catch (_) {
    return null;
  }
};

const clearPersistentPlaybackSession = () => {
  persistentPlaybackSession = null;
  try { localStorage.removeItem(PERSISTENT_PLAYBACK_KEY); } catch (_) {}
  window.dispatchEvent(new CustomEvent(PERSISTENT_PLAYBACK_EVENT, { detail: { session: null, video: null } }));
};

const categories = ['All', 'Cinematography', 'Editing', 'Color Grading', 'VFX', 'Documentary', 'Gear Reviews', 'Tutorials', 'Behind the Scenes', 'Live Streams', 'Shorts'];

const messageTabs = [
  { id: 'primary', label: 'Primary' },
  { id: 'requests', label: 'Requests' },
  { id: 'mentions', label: 'Mentions' },
];

function formatNumber(value = 0) {
  if (value >= 1000000) return `${(value / 1000000).toFixed(value >= 10000000 ? 0 : 1)}M`;
  if (value >= 1000) return `${(value / 1000).toFixed(value >= 100000 ? 0 : 1)}K`;
  return String(value);
}

function assetUrl(value) {
  if (!value) return '';
  if (/^(https?:)?\/\//.test(value) || value.startsWith('/')) return value;
  return `/uploads/${value.replace(/^public\//, '')}`;
}

const ACCOUNT_STORE_KEY = 'playhub_accounts_v1';
const ACCOUNT_SESSION_STORE_KEY = 'playhub_session_accounts_v1';
const MAX_SWITCH_ACCOUNTS = 6;

function storageForAccount(remember = true) {
  if (typeof window === 'undefined') return null;
  try { return remember ? window.localStorage : window.sessionStorage; } catch (_) { return null; }
}

function readAccountBucket(remember = true) {
  const storage = storageForAccount(remember);
  if (!storage) return [];
  const key = remember ? ACCOUNT_STORE_KEY : ACCOUNT_SESSION_STORE_KEY;
  try {
    const rows = JSON.parse(storage.getItem(key) || '[]');
    if (!Array.isArray(rows)) return [];
    return rows
      .filter((row) => row && row.id && row.token)
      .map((row) => ({ ...row, remember }));
  } catch (_) {
    return [];
  }
}

function writeAccountBucket(remember = true, accounts = []) {
  const storage = storageForAccount(remember);
  if (!storage) return;
  const key = remember ? ACCOUNT_STORE_KEY : ACCOUNT_SESSION_STORE_KEY;
  try {
    storage.setItem(key, JSON.stringify(accounts.slice(0, MAX_SWITCH_ACCOUNTS)));
  } catch (_) {}
}

function currentTokenRemembered() {
  try { return Boolean(window.localStorage.getItem('playhub_token')); } catch (_) { return true; }
}

function accountStorageSnapshot(user, token, remember = true) {
  if (!user || !token) return null;
  const channel = user.channel || {};
  const id = String(user.id || user.email || channel.id || token.slice(-18));
  const handle = user.handle || user.username || channel.handle || (channel.slug ? `@${channel.slug}` : '') || user.email || '';
  return {
    id,
    token,
    remember: Boolean(remember),
    name: user.name || channel.name || user.email || 'Account',
    email: user.email || '',
    handle,
    avatar: channel.avatar_url || channel.avatar_path || user.avatar_url || user.avatar_path || '',
    saved_at: Date.now(),
  };
}

function removeStoredAccount(match = {}) {
  [true, false].forEach((remember) => {
    const next = readAccountBucket(remember).filter((account) => {
      if (match.id && String(account.id) === String(match.id)) return false;
      if (match.token && account.token === match.token) return false;
      return true;
    });
    writeAccountBucket(remember, next);
  });
}

function saveStoredAccount(user, token = api.token(), remember = currentTokenRemembered()) {
  const snapshot = accountStorageSnapshot(user, token, remember);
  if (!snapshot) return null;
  removeStoredAccount({ id: snapshot.id, token: snapshot.token });
  const bucket = readAccountBucket(snapshot.remember);
  writeAccountBucket(snapshot.remember, [snapshot, ...bucket].slice(0, MAX_SWITCH_ACCOUNTS));
  return snapshot;
}

function readStoredAccounts() {
  const merged = [...readAccountBucket(true), ...readAccountBucket(false)]
    .filter((account) => account?.id && account?.token)
    .sort((a, b) => Number(b.saved_at || 0) - Number(a.saved_at || 0));
  const seen = new Set();
  return merged.filter((account) => {
    const key = String(account.id);
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

function cssVarName(key) {
  return String(key || '').replace(/[A-Z]/g, (match) => `-${match.toLowerCase()}`);
}

function setSeoMeta(attribute, key, content) {
  let element = document.head.querySelector(`meta[${attribute}="${key}"]`);
  if (content === null || content === undefined || content === '') {
    element?.remove();
    return;
  }
  if (!element) {
    element = document.createElement('meta');
    element.setAttribute(attribute, key);
    document.head.appendChild(element);
  }
  element.setAttribute('content', String(content));
}

function applySeoMetadata(metadata = {}) {
  if (typeof document === 'undefined' || !metadata?.url) return;
  document.title = metadata.browser_title || metadata.title || document.title;
  // I18nProvider owns the interface language. Social/video metadata can have a
  // different locale and must not override the reader's preference.

  setSeoMeta('name', 'description', metadata.description);
  setSeoMeta('name', 'robots', metadata.robots);
  setSeoMeta('name', 'keywords', metadata.keywords);
  setSeoMeta('name', 'google-site-verification', metadata.google_site_verification);
  setSeoMeta('name', 'msvalidate.01', metadata.bing_site_verification);
  setSeoMeta('property', 'og:site_name', metadata.site_name);
  setSeoMeta('property', 'og:locale', metadata.locale);
  setSeoMeta('property', 'og:type', metadata.type);
  setSeoMeta('property', 'og:title', metadata.title);
  setSeoMeta('property', 'og:description', metadata.description);
  setSeoMeta('property', 'og:url', metadata.url);
  setSeoMeta('property', 'og:image', metadata.image);
  setSeoMeta('property', 'og:image:url', metadata.image);
  setSeoMeta('property', 'og:image:secure_url', String(metadata.image || '').startsWith('https://') ? metadata.image : '');
  setSeoMeta('property', 'og:image:type', metadata.image_type);
  setSeoMeta('property', 'og:image:width', metadata.image_width);
  setSeoMeta('property', 'og:image:height', metadata.image_height);
  setSeoMeta('property', 'og:image:alt', metadata.image_alt);
  setSeoMeta('property', 'profile:username', metadata.profile_username);
  setSeoMeta('property', 'article:published_time', metadata.type === 'article' ? metadata.published_time : '');
  setSeoMeta('property', 'video:release_date', metadata.type !== 'article' ? metadata.published_time : '');
  setSeoMeta('property', 'video:duration', metadata.video_duration);
  setSeoMeta('name', 'twitter:card', 'summary_large_image');
  setSeoMeta('name', 'twitter:site', metadata.twitter_site);
  setSeoMeta('name', 'twitter:title', metadata.title);
  setSeoMeta('name', 'twitter:description', metadata.description);
  setSeoMeta('name', 'twitter:url', metadata.url);
  setSeoMeta('name', 'twitter:image', metadata.image);
  setSeoMeta('name', 'twitter:image:alt', metadata.image_alt);

  document.head.querySelectorAll('meta[data-playhub-custom-meta]').forEach((element) => element.remove());
  (Array.isArray(metadata.custom_meta_tags) ? metadata.custom_meta_tags : []).forEach((tag) => {
    if (!['name', 'property'].includes(tag?.attribute) || !tag?.key || !tag?.content) return;
    const element = document.createElement('meta');
    element.setAttribute(tag.attribute, String(tag.key));
    element.setAttribute('content', String(tag.content));
    element.dataset.playhubCustomMeta = 'true';
    document.head.appendChild(element);
  });

  let canonical = document.head.querySelector('link[rel="canonical"]');
  if (!canonical) {
    canonical = document.createElement('link');
    canonical.rel = 'canonical';
    document.head.appendChild(canonical);
  }
  canonical.href = metadata.url;

  let structuredData = document.getElementById('playhub-structured-data');
  if (metadata.structured_data) {
    if (!structuredData) {
      structuredData = document.createElement('script');
      structuredData.id = 'playhub-structured-data';
      structuredData.type = 'application/ld+json';
      document.head.appendChild(structuredData);
    }
    structuredData.textContent = JSON.stringify(metadata.structured_data);
  } else {
    structuredData?.remove();
  }
}

function applyWebsiteConfiguration(website = {}, theme = 'light', user = null) {
  if (typeof document === 'undefined') return;
  const root = document.documentElement;
  const config = website && typeof website === 'object' ? website : {};
  const design = config.design && typeof config.design === 'object' ? config.design : {};
  const userAccent = user?.settings?.appearance?.accent;
  const hasUserAccent = userAccent && ACCENT_PALETTES[userAccent];
  const themeKey = theme === 'dark' ? 'darkColors' : 'colors';
  const adminThemeKey = theme === 'dark' ? 'adminDarkColors' : 'adminColors';
  const colors = design[themeKey] && typeof design[themeKey] === 'object' ? design[themeKey] : {};
  const adminColors = design[adminThemeKey] && typeof design[adminThemeKey] === 'object' ? design[adminThemeKey] : {};

  window.__PLAYHUB_WEBSITE__ = config;
  window.__PLAYHUB_APPLY_WEBSITE__ = applyWebsiteConfiguration;
  root.classList.toggle('sidebar-toggle-disabled', config.showSidebarToggle === false);
  root.style.setProperty('--website-logo-size', `${Math.max(16, Math.min(64, Number(config.logoSize) || 40))}px`);
  window.dispatchEvent?.(new CustomEvent('playhub:website-config'));

  if (config.websiteTitle) document.title = config.websiteTitle;
  const faviconUrl = assetUrl(config.faviconUrl);
  let favicon = document.querySelector('link[rel="icon"]');
  if (faviconUrl) {
    if (!favicon) {
      favicon = document.createElement('link');
      favicon.rel = 'icon';
      document.head.appendChild(favicon);
    }
    favicon.href = faviconUrl;
  }

  let fontImport = document.getElementById('playhub-font-import');
  if (config.fontImportUrl) {
    if (!fontImport) {
      fontImport = document.createElement('link');
      fontImport.id = 'playhub-font-import';
      fontImport.rel = 'stylesheet';
      document.head.appendChild(fontImport);
    }
    fontImport.href = config.fontImportUrl;
  } else if (fontImport) {
    fontImport.remove();
  }

  if (config.fontFamily) root.style.setProperty('--font', config.fontFamily);
  Object.entries(colors).forEach(([key, value]) => {
    if (value !== null && value !== undefined && value !== '') root.style.setProperty(`--${cssVarName(key)}`, value);
  });
  Object.entries(adminColors).forEach(([key, value]) => {
    if (value !== null && value !== undefined && value !== '') root.style.setProperty(`--website-admin-${cssVarName(key)}`, value);
  });

  const defaultPrimary = config.defaultPrimaryColor || colors.primary || '#b68a2d';
  const defaultSecondary = config.defaultSecondaryColor || colors['primary-2'] || '#6f5119';
  const defaultPalette = Object.values(ACCENT_PALETTES).find((palette) => palette.primary.toLowerCase() === String(defaultPrimary).toLowerCase());
  const userPalette = hasUserAccent ? ACCENT_PALETTES[userAccent] : null;
  const defaultSoft = theme === 'dark'
    ? (defaultPalette?.softDark || colors['primary-soft'] || 'rgba(208,170,88,.22)')
    : (config.defaultPrimarySoftColor || defaultPalette?.softLight || colors['primary-soft'] || '#fff2cf');
  root.style.setProperty('--viewer-accent-ink', accentInk(userPalette?.primary || defaultPrimary));
  root.style.setProperty('--website-admin-primary', userPalette?.primary || defaultPrimary);
  root.style.setProperty('--website-admin-primary-2', userPalette?.primary2 || defaultSecondary);
  root.style.setProperty('--website-admin-primary-soft', userPalette ? (theme === 'dark' ? userPalette.softDark : userPalette.softLight) : defaultSoft);

  if (hasUserAccent) {
    root.style.setProperty('--primary', userPalette.primary);
    root.style.setProperty('--primary-2', userPalette.primary2);
    root.style.setProperty('--primary-soft', theme === 'dark' ? userPalette.softDark : userPalette.softLight);
  } else {
    root.style.setProperty('--primary', defaultPrimary);
    root.style.setProperty('--primary-2', defaultSecondary);
    const softDefault = theme === 'dark'
      ? (colors['primary-soft'] || 'rgba(208,170,88,.22)')
      : (config.defaultPrimarySoftColor || colors['primary-soft'] || '#fff2cf');
    root.style.setProperty('--primary-soft', softDefault);
  }

  Object.entries(design.fontSizes || {}).forEach(([key, value]) => {
    if (value) root.style.setProperty(`--${cssVarName(key)}-font-size`, value);
  });
  Object.entries(design.fontWeights || {}).forEach(([key, value]) => {
    if (value) root.style.setProperty(`--font-weight-${cssVarName(key)}`, value);
  });
  Object.entries(design.radii || {}).forEach(([key, value]) => {
    if (value) root.style.setProperty(`--${cssVarName(key)}`, value);
  });
  Object.entries(design.layout || {}).forEach(([key, value]) => {
    if (!value) return;
    if (key === 'adminSidebarWidth') {
      root.style.setProperty('--website-admin-sidebar-width', value);
      return;
    }
    root.style.setProperty(`--${cssVarName(key)}`, value);
  });
}

function currentWebsiteConfiguration() {
  return typeof window !== 'undefined' && window.__PLAYHUB_WEBSITE__ ? window.__PLAYHUB_WEBSITE__ : {};
}

function websiteName(config = null) {
  const website = config || currentWebsiteConfiguration();
  return String(website.platformName || '').trim() || 'PlayHub';
}

function websiteText(value, config = null) {
  return brandedProjectText(value, websiteName(config));
}

function websiteCopy(value) {
  if (Array.isArray(value)) return value.map(websiteCopy);
  if (value && typeof value === 'object') return Object.fromEntries(Object.entries(value).map(([key, item]) => [key, websiteCopy(item)]));
  return typeof value === 'string' ? websiteText(value) : value;
}

function useWebsiteConfiguration(override = null) {
  const [website, setWebsite] = useState(() => override || currentWebsiteConfiguration());
  useEffect(() => {
    if (override) {
      setWebsite(override);
      return undefined;
    }
    const refresh = () => setWebsite({ ...currentWebsiteConfiguration() });
    window.addEventListener('playhub:website-config', refresh);
    refresh();
    return () => window.removeEventListener('playhub:website-config', refresh);
  }, [override]);
  return override || website;
}

function websiteBrand(config = null) {
  const website = config || currentWebsiteConfiguration();
  return {
    text: String(website.logoText ?? websiteName(website)).trim(),
    showText: website.showLogoText !== false,
    size: Math.max(16, Math.min(64, Number(website.logoSize) || 40)),
    name: websiteName(website),
    logoUrl: assetUrl(website.logoUrl),
  };
}

function isSvgLogoUrl(value) {
  return /\.svg(?:$|[?#])/i.test(String(value || ''));
}

function logoMaskStyle(value) {
  return { '--logo-url': `url("${String(value || '').replace(/\\/g, '\\\\').replace(/"/g, '\\"')}")` };
}

function profilePathFor(entity) {
  const channel = entity?.channel || entity;
  const directPath = channel?.profile_path || channel?.profilePath || channel?.profile_url || channel?.profileUrl;
  if (typeof directPath === 'string' && directPath.startsWith('/channel/')) return directPath;
  const slug = channel?.slug || channel?.channel_slug;
  return slug ? `/channel/${encodeURIComponent(slug)}` : '';
}

const MOBILE_MENU_SURFACE_SELECTOR = [
  '.topbar-account-menu.rich',
  '.messages-popover',
  '.notifications-popover',
  '.comment-action-menu',
  '.search-video-action-menu',
  '.playlist-row-action-menu',
  '.shorts-detail-action-menu',
  '.video-detail-action-menu',
  '.content-bulk-action-menu',
  '.content-row-action-menu',
  '.profile-action-menu',
  '.channel-featured-action-menu',
  '.community-post-menu',
  '.content-filter-menu',
  '.content-sort-menu',
  '.comment-sticker-picker',
].join(',');

function isTouchMenuTrigger(button) {
  if (!button || button.disabled) return false;
  const label = `${button.getAttribute('aria-label') || ''} ${button.textContent || ''}`.toLowerCase();
  if (button.getAttribute('aria-haspopup') === 'menu') return true;
  if (button.hasAttribute('aria-expanded') && /(more|actions|options)/.test(label)) return true;
  if (button.classList.contains('profile-more-button') || button.classList.contains('community-post-menu-trigger')) return true;
  return Boolean(button.closest('.playlist-row-menu-shell,.shorts-detail-more-shell'));
}

function isMobileMenuCloseZone(menu, event) {
  const rect = menu?.getBoundingClientRect?.();
  const clientX = Number(event?.clientX);
  const clientY = Number(event?.clientY);
  if (!rect || !Number.isFinite(clientX) || !Number.isFinite(clientY)) return false;
  const closeStyle = window.getComputedStyle?.(menu, '::after');
  if (!closeStyle || ['none', 'normal', '""'].includes(closeStyle.content)) return false;
  const valueOr = (value, fallback) => {
    const parsed = Number.parseFloat(value);
    return Number.isFinite(parsed) ? parsed : fallback;
  };
  const size = valueOr(closeStyle?.width, 36);
  const height = valueOr(closeStyle?.height, size);
  const top = valueOr(closeStyle?.top, 8);
  const right = valueOr(closeStyle?.right, 12);
  const padding = 4;
  return clientY >= rect.top + top - padding
    && clientY <= rect.top + top + height + padding
    && clientX >= rect.right - right - size - padding
    && clientX <= rect.right - right + padding;
}

function closeMobileMenuSurface(menu) {
  if (!menu || menu.classList.contains('mobile-sheet-closing')) return;
  menu.classList.remove('mobile-sheet-dragging');
  menu.style.removeProperty('transform');
  menu.style.removeProperty('transition');
  menu.style.removeProperty('animation');
  menu.classList.add('mobile-sheet-closing');
  window.setTimeout(() => {
    const escapeEvent = new KeyboardEvent('keydown', { key: 'Escape', bubbles: true });
    document.dispatchEvent(escapeEvent);
    document.body?.dispatchEvent(new MouseEvent('mousedown', { bubbles: true, cancelable: true, view: window }));
    menu.classList.remove('mobile-sheet-closing', 'mobile-sheet-dragging');
    menu.style.removeProperty('transform');
    menu.style.removeProperty('transition');
    menu.style.removeProperty('animation');
    menu.style.removeProperty('--mobile-sheet-drag-y');
  }, 280);
}


function prefersNativeEmojiKeyboard() {
  if (typeof window === 'undefined') return false;
  return window.matchMedia?.('(hover: none), (pointer: coarse)')?.matches || window.innerWidth <= 640;
}

function isEmojiTextInput(node) {
  if (!node || node.disabled || node.readOnly) return false;
  const tagName = String(node.tagName || '').toLowerCase();
  if (tagName === 'textarea') return true;
  if (tagName !== 'input') return false;
  const type = String(node.getAttribute('type') || 'text').toLowerCase();
  return !['button', 'checkbox', 'file', 'hidden', 'image', 'radio', 'range', 'reset', 'submit'].includes(type);
}

function focusNativeEmojiInput(input) {
  if (!isEmojiTextInput(input)) return false;
  const cursor = input.selectionStart ?? String(input.value || '').length;
  const focus = () => {
    input.focus({ preventScroll: true });
    input.setSelectionRange?.(cursor, cursor);
  };
  focus();
  window.requestAnimationFrame(focus);
  return true;
}

function nativeEmojiInputFor(button) {
  const selector = 'textarea:not([disabled]):not([readonly]),input:not([disabled]):not([readonly]):not([type="button"]):not([type="checkbox"]):not([type="file"]):not([type="hidden"]):not([type="image"]):not([type="radio"]):not([type="range"]):not([type="reset"]):not([type="submit"])';
  const roots = [
    button.closest('.comment-composer-field'),
    button.closest('.message-composer-field'),
    button.closest('.private-chat-input-row'),
    button.closest('.search-community-comment-field'),
    button.closest('.community-composer-field'),
    button.closest('.community-post-edit-field'),
    button.closest('form'),
    button.closest('.comment-emoji-wrapper')?.parentElement,
  ].filter(Boolean);
  for (const root of roots) {
    const input = root.querySelector?.(selector);
    if (input) return input;
  }
  return isEmojiTextInput(document.activeElement) ? document.activeElement : null;
}

function useNativeEmojiKeyboardOnMobile() {
  useEffect(() => {
    if (typeof document === 'undefined') return undefined;
    const openNativeEmojiKeyboard = (event) => {
      if (!prefersNativeEmojiKeyboard()) return;
      const button = event.target?.closest?.('.comment-emoji-button[aria-label="Add emoji"]');
      if (!button) return;
      const input = nativeEmojiInputFor(button);
      if (!input) return;
      event.preventDefault();
      event.stopPropagation();
      event.stopImmediatePropagation?.();
      document.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', bubbles: true }));
      focusNativeEmojiInput(input);
    };
    document.addEventListener('click', openNativeEmojiKeyboard, true);
    return () => document.removeEventListener('click', openNativeEmojiKeyboard, true);
  }, []);
}


function useMobileNavAutoHide(routeKey = '', overlayOpen = false) {
  useEffect(() => {
    if (typeof window === 'undefined' || typeof document === 'undefined') return undefined;
    const mobileQuery = window.matchMedia?.('(max-width: 860px)');
    const root = document.documentElement;
    const body = document.body;
    let lastY = Math.max(0, window.scrollY || root.scrollTop || 0);
    let frame = 0;

    const isMobile = () => mobileQuery?.matches ?? window.innerWidth <= 860;
    const currentY = () => Math.max(0, window.scrollY || root.scrollTop || body.scrollTop || 0);
    const setHidden = (nextHidden) => {
      root.classList.toggle('mobile-nav-scroll-hidden', nextHidden);
      body.classList.toggle('mobile-nav-scroll-hidden', nextHidden);
    };
    const hasActiveMobileOverlay = () => (
      root.classList.contains('mobile-menu-sheet-open')
      || body.classList.contains('mobile-menu-sheet-open')
      || root.classList.contains('mobile-sidebar-scroll-locked')
      || body.classList.contains('mobile-sidebar-scroll-locked')
      || Boolean(document.querySelector('.app-shell.mobile-nav-open'))
    );
    const update = () => {
      frame = 0;
      const y = currentY();
      if (!isMobile() || overlayOpen || hasActiveMobileOverlay()) {
        setHidden(false);
        lastY = y;
        return;
      }
      const maxY = Math.max(0, root.scrollHeight - window.innerHeight);
      const delta = y - lastY;
      if (y <= 24 || maxY - y <= 24) {
        setHidden(false);
        lastY = y;
        return;
      }
      if (Math.abs(delta) < 8) return;
      if (delta > 0 && y > 96) setHidden(true);
      if (delta < 0) setHidden(false);
      lastY = y;
    };
    const schedule = () => {
      if (!frame) frame = window.requestAnimationFrame(update);
    };
    const reset = () => {
      window.cancelAnimationFrame(frame);
      frame = 0;
      lastY = currentY();
      setHidden(false);
    };

    reset();
    window.addEventListener('scroll', schedule, { passive: true });
    window.addEventListener('resize', reset);
    mobileQuery?.addEventListener?.('change', reset);
    return () => {
      window.cancelAnimationFrame(frame);
      window.removeEventListener('scroll', schedule);
      window.removeEventListener('resize', reset);
      mobileQuery?.removeEventListener?.('change', reset);
      root.classList.remove('mobile-nav-scroll-hidden');
      body.classList.remove('mobile-nav-scroll-hidden');
    };
  }, [routeKey, overlayOpen]);
}

function useMobileMenuInteractions() {
  useEffect(() => {
    if (typeof window === 'undefined' || typeof document === 'undefined') return undefined;
    const coarseQuery = window.matchMedia?.('(hover: none), (pointer: coarse)');
    const sheetQuery = window.matchMedia?.('(max-width: 860px)');
    const isTouchLike = () => (coarseQuery?.matches ?? true) && (sheetQuery?.matches ?? window.innerWidth <= 860);
    const isSheetSurfaceEnabled = (menu) => !menu?.classList?.contains('comment-sticker-picker') || window.innerWidth <= 520;
    let longPressTimer = 0;
    let longPressTrigger = null;
    let longPressStart = null;
    let longPressFired = false;
    let suppressClickUntil = 0;
    let suppressClickTarget = null;
    let activeMenu = null;
    let sheetMask = null;
    let sheetScrollLock = null;
    let maskCleanupTimer = 0;
    let refreshTimer = 0;
    let sheetDrag = null;
    let sheetSnapTimer = 0;
    let sheetDragFrame = 0;
    let promotedMenu = null;

    const releasePromotedMenu = () => {
      const menu = promotedMenu;
      promotedMenu = null;
      if (!menu?.isConnected) return;
      try {
        if (menu.matches(':popover-open')) menu.hidePopover();
      } catch {}
      menu.removeAttribute('popover');
      menu.classList.remove('mobile-sheet-top-layer');
    };
    const promoteSheetMenu = (menu) => {
      if (promotedMenu && promotedMenu !== menu) releasePromotedMenu();
      if (!menu || menu.parentElement === document.body) return true;
      if (typeof menu.showPopover !== 'function') return false;
      try {
        menu.setAttribute('popover', 'manual');
        menu.classList.add('mobile-sheet-top-layer');
        if (!menu.matches(':popover-open')) menu.showPopover();
        promotedMenu = menu;
        return true;
      } catch {
        menu.removeAttribute('popover');
        menu.classList.remove('mobile-sheet-top-layer');
        return false;
      }
    };

    const stopSheetBackgroundScroll = (event) => {
      if (event.target?.closest?.(`${MOBILE_MENU_SURFACE_SELECTOR},.language-dialog,.playlist-modal`)) return;
      event.preventDefault();
    };
    const lockSheetBackgroundScroll = () => {
      if (sheetScrollLock) return;
      const html = document.documentElement;
      const body = document.body;
      sheetScrollLock = {
        htmlOverflow: html.style.overflow,
        bodyOverflow: body.style.overflow,
        htmlOverscroll: html.style.overscrollBehavior,
        bodyOverscroll: body.style.overscrollBehavior,
      };
      html.style.overflow = 'hidden';
      body.style.overflow = 'hidden';
      html.style.overscrollBehavior = 'none';
      body.style.overscrollBehavior = 'none';
      document.addEventListener('touchmove', stopSheetBackgroundScroll, { passive: false });
      document.addEventListener('wheel', stopSheetBackgroundScroll, { passive: false });
    };
    const unlockSheetBackgroundScroll = () => {
      if (!sheetScrollLock) return;
      const html = document.documentElement;
      const body = document.body;
      document.removeEventListener('touchmove', stopSheetBackgroundScroll);
      document.removeEventListener('wheel', stopSheetBackgroundScroll);
      html.style.overflow = sheetScrollLock.htmlOverflow;
      body.style.overflow = sheetScrollLock.bodyOverflow;
      html.style.overscrollBehavior = sheetScrollLock.htmlOverscroll;
      body.style.overscrollBehavior = sheetScrollLock.bodyOverscroll;
      sheetScrollLock = null;
    };

    const visibleMenu = (menu) => {
      if (!menu || !isSheetSurfaceEnabled(menu) || menu.classList?.contains('mobile-sheet-closing')) return false;
      const rect = menu.getBoundingClientRect?.();
      return Boolean(rect && rect.width > 0 && rect.height > 0);
    };
    const removeSheetMask = () => {
      if (!sheetMask) return;
      window.clearTimeout(maskCleanupTimer);
      const mask = sheetMask;
      sheetMask = null;
      mask.classList.add('closing');
      mask.classList.remove('open');
      document.documentElement.classList.remove('mobile-menu-sheet-open');
      document.body.classList.remove('mobile-menu-sheet-open');
      unlockSheetBackgroundScroll();
      maskCleanupTimer = window.setTimeout(() => {
        mask.remove();
        maskCleanupTimer = 0;
      }, 280);
    };
    const ensureSheetMask = () => {
      if (sheetMask) return;
      const mask = document.createElement('button');
      mask.type = 'button';
      mask.className = 'mobile-menu-sheet-mask';
      mask.setAttribute('aria-label', 'Close');
      const closeFromMask = (event) => {
        event.preventDefault();
        event.stopPropagation();
        closeMobileMenuSurface(activeMenu);
        removeSheetMask();
      };
      const stopMaskEvent = (event) => {
        event.preventDefault();
        event.stopPropagation();
      };
      mask.addEventListener('pointerdown', closeFromMask, { passive: false });
      mask.addEventListener('mousedown', stopMaskEvent, { passive: false });
      mask.addEventListener('click', stopMaskEvent, { passive: false });
      document.body.appendChild(mask);
      sheetMask = mask;
      document.documentElement.classList.add('mobile-menu-sheet-open');
      document.body.classList.add('mobile-menu-sheet-open');
      lockSheetBackgroundScroll();
      window.requestAnimationFrame(() => mask.classList.add('open'));
    };
    const refreshSheetMask = () => {
      if (!isTouchLike()) {
        activeMenu = null;
        releasePromotedMenu();
        removeSheetMask();
        return;
      }
      const menus = Array.from(document.querySelectorAll(MOBILE_MENU_SURFACE_SELECTOR)).filter(visibleMenu);
      activeMenu = menus.length ? menus[menus.length - 1] : null;
      if (activeMenu && promoteSheetMenu(activeMenu)) ensureSheetMask();
      else {
        if (promotedMenu && !promotedMenu.isConnected) promotedMenu = null;
        removeSheetMask();
      }
    };
    const scheduleRefresh = () => {
      window.clearTimeout(refreshTimer);
      refreshTimer = window.setTimeout(refreshSheetMask, 0);
    };

    const resetSheetDragStyles = (menu) => {
      window.cancelAnimationFrame(sheetDragFrame);
      sheetDragFrame = 0;
      if (sheetMask) sheetMask.style.removeProperty('opacity');
      if (!menu) return;
      menu.classList.remove('mobile-sheet-dragging');
      menu.style.removeProperty('transform');
      menu.style.removeProperty('transition');
      menu.style.removeProperty('animation');
      menu.style.removeProperty('--mobile-sheet-drag-y');
    };
    const sheetTouchPoint = (event, identifier = null) => {
      const touches = Array.from(event.changedTouches || event.touches || []);
      if (identifier === null) return touches[0] || null;
      return touches.find((touch) => touch.identifier === identifier) || null;
    };
    const startSheetDrag = (event) => {
      if (!isTouchLike() || event.touches?.length !== 1) return;
      const touch = sheetTouchPoint(event);
      const menu = event.target.closest?.(MOBILE_MENU_SURFACE_SELECTOR);
      if (!touch || !menu || !isSheetSurfaceEnabled(menu) || menu.classList.contains('mobile-sheet-closing')) return;
      if (isMobileMenuCloseZone(menu, touch)) {
        event.preventDefault();
        event.stopPropagation();
        closeMobileMenuSurface(menu);
        removeSheetMask();
        return;
      }
      if (event.target.closest?.('input,textarea,select,option')) return;
      window.clearTimeout(sheetSnapTimer);
      resetSheetDragStyles(menu);
      sheetDrag = {
        menu,
        identifier: touch.identifier,
        startX: touch.clientX,
        startY: touch.clientY,
        lastY: touch.clientY,
        lastTime: Date.now(),
        currentY: 0,
        pendingY: 0,
        velocity: 0,
        dragging: false,
        scrollElement: event.target.closest?.('.comment-sticker-grid') || menu,
      };
    };
    const applySheetDragFrame = () => {
      const drag = sheetDrag;
      sheetDragFrame = 0;
      if (!drag?.dragging) return;
      const offset = Math.max(0, drag.pendingY || 0);
      drag.currentY = offset;
      drag.menu.style.setProperty('--mobile-sheet-drag-y', offset + 'px');
      if (sheetMask) sheetMask.style.opacity = String(Math.max(0.28, 1 - (offset / 360)));
    };
    const scheduleSheetDragFrame = () => {
      if (!sheetDragFrame) sheetDragFrame = window.requestAnimationFrame(applySheetDragFrame);
    };
    const moveSheetDrag = (event) => {
      if (!sheetDrag) return;
      const touch = sheetTouchPoint(event, sheetDrag.identifier);
      if (!touch) return;
      const dx = touch.clientX - sheetDrag.startX;
      const dy = touch.clientY - sheetDrag.startY;
      const now = Date.now();
      if (!sheetDrag.dragging) {
        if (dy < 8 || Math.abs(dy) <= Math.abs(dx)) return;
        if (sheetDrag.scrollElement.scrollTop > 2) {
          sheetDrag.startX = touch.clientX;
          sheetDrag.startY = touch.clientY;
          sheetDrag.lastY = touch.clientY;
          sheetDrag.lastTime = now;
          return;
        }
        sheetDrag.dragging = true;
        sheetDrag.menu.classList.add('mobile-sheet-dragging');
        sheetDrag.menu.style.setProperty('--mobile-sheet-drag-y', '0px');
        clearLongPress();
      }
      if (event.cancelable) event.preventDefault();
      event.stopPropagation();
      const offset = Math.max(0, dy);
      const elapsed = Math.max(1, now - sheetDrag.lastTime);
      const instantVelocity = (touch.clientY - sheetDrag.lastY) / elapsed;
      sheetDrag.velocity = (sheetDrag.velocity * 0.35) + (instantVelocity * 0.65);
      sheetDrag.pendingY = offset;
      sheetDrag.currentY = offset;
      sheetDrag.lastY = touch.clientY;
      sheetDrag.lastTime = now;
      scheduleSheetDragFrame();
    };
    const finishSheetDrag = (event) => {
      if (!sheetDrag) return false;
      const touch = sheetTouchPoint(event, sheetDrag.identifier);
      const drag = sheetDrag;
      sheetDrag = null;
      if (!drag.dragging) return false;
      if (event.cancelable) event.preventDefault();
      event.stopPropagation();
      suppressClickTarget = drag.menu;
      suppressClickUntil = Date.now() + 500;
      window.cancelAnimationFrame(sheetDragFrame);
      sheetDragFrame = 0;
      const releaseY = touch?.clientY ?? drag.lastY;
      const elapsed = Math.max(1, Date.now() - drag.lastTime);
      const releaseVelocity = (releaseY - drag.lastY) / elapsed;
      const velocity = Math.max(drag.velocity || 0, releaseVelocity);
      const offset = Math.max(0, drag.pendingY || drag.currentY || 0);
      drag.currentY = offset;
      drag.menu.style.setProperty('--mobile-sheet-drag-y', offset + 'px');
      if (sheetMask) sheetMask.style.removeProperty('opacity');
      const closeDistance = Math.min(132, drag.menu.offsetHeight * 0.3);
      const shouldClose = offset > closeDistance || velocity > 0.45;
      if (shouldClose) {
        drag.menu.style.removeProperty('transition');
        drag.menu.style.removeProperty('animation');
        closeMobileMenuSurface(drag.menu);
        removeSheetMask();
      } else {
        drag.menu.style.transition = 'none';
        drag.menu.style.transform = 'translate3d(0,' + offset + 'px,0)';
        drag.menu.classList.remove('mobile-sheet-dragging');
        drag.menu.style.animation = 'none';
        drag.menu.getBoundingClientRect();
        drag.menu.style.transition = 'transform .24s cubic-bezier(.22,1,.36,1)';
        drag.menu.style.transform = 'translate3d(0,0,0)';
        sheetSnapTimer = window.setTimeout(() => resetSheetDragStyles(drag.menu), 260);
      }
      return true;
    };

    const clearLongPress = () => {
      window.clearTimeout(longPressTimer);
      longPressTimer = 0;
      longPressTrigger = null;
      longPressStart = null;
    };
    const openByLongPress = () => {
      if (!longPressTrigger?.isConnected) return;
      longPressFired = true;
      suppressClickTarget = longPressTrigger;
      suppressClickUntil = Date.now() + 700;
      longPressTrigger.click();
      navigator.vibrate?.(8);
    };
    const onPointerDown = (event) => {
      if (!isTouchLike() || event.pointerType === 'mouse' || event.button) return;
      const menu = event.target.closest?.(MOBILE_MENU_SURFACE_SELECTOR);
      if (menu && isMobileMenuCloseZone(menu, event)) {
        event.preventDefault();
        event.stopPropagation();
        closeMobileMenuSurface(menu);
        removeSheetMask();
        return;
      }
      const button = event.target.closest?.('button');
      if (!isTouchMenuTrigger(button)) return;
      longPressFired = false;
      longPressTrigger = button;
      longPressStart = { x: event.clientX, y: event.clientY };
      longPressTimer = window.setTimeout(openByLongPress, 520);
    };
    const onPointerMove = (event) => {
      if (longPressStart && (Math.abs(event.clientX - longPressStart.x) > 10 || Math.abs(event.clientY - longPressStart.y) > 10)) clearLongPress();
    };
    const onPointerUp = (event) => {
      if (longPressFired && suppressClickTarget) event.preventDefault();
      clearLongPress();
    };
    const onClickCapture = (event) => {
      scheduleRefresh();
      if (!suppressClickTarget || Date.now() > suppressClickUntil) return;
      if (event.target === suppressClickTarget || suppressClickTarget.contains(event.target)) {
        event.preventDefault();
        event.stopPropagation();
      }
    };

    const observer = new MutationObserver(refreshSheetMask);
    observer.observe(document.body, { childList: true, subtree: true });
    document.addEventListener('pointerdown', onPointerDown, { capture: true, passive: false });
    document.addEventListener('pointermove', onPointerMove, { capture: true, passive: false });
    document.addEventListener('pointerup', onPointerUp, { capture: true, passive: false });
    document.addEventListener('pointercancel', onPointerUp, { capture: true, passive: false });
    document.addEventListener('touchstart', startSheetDrag, { capture: true, passive: false });
    document.addEventListener('touchmove', moveSheetDrag, { capture: true, passive: false });
    document.addEventListener('touchend', finishSheetDrag, { capture: true, passive: false });
    document.addEventListener('touchcancel', finishSheetDrag, { capture: true, passive: false });
    document.addEventListener('click', onClickCapture, true);
    window.addEventListener('resize', refreshSheetMask);
    refreshSheetMask();
    return () => {
      clearLongPress();
      observer.disconnect();
      removeSheetMask();
      window.clearTimeout(maskCleanupTimer);
      document.querySelectorAll('.mobile-menu-sheet-mask').forEach((mask) => mask.remove());
      releasePromotedMenu();
      window.clearTimeout(refreshTimer);
      window.clearTimeout(sheetSnapTimer);
      window.cancelAnimationFrame(sheetDragFrame);
      document.querySelectorAll(MOBILE_MENU_SURFACE_SELECTOR).forEach(resetSheetDragStyles);
      window.removeEventListener('resize', refreshSheetMask);
      document.removeEventListener('pointerdown', onPointerDown, true);
      document.removeEventListener('pointermove', onPointerMove, true);
      document.removeEventListener('pointerup', onPointerUp, true);
      document.removeEventListener('pointercancel', onPointerUp, true);
      document.removeEventListener('touchstart', startSheetDrag, true);
      document.removeEventListener('touchmove', moveSheetDrag, true);
      document.removeEventListener('touchend', finishSheetDrag, true);
      document.removeEventListener('touchcancel', finishSheetDrag, true);
      document.removeEventListener('click', onClickCapture, true);
    };
  }, []);
}

function canAccessAdmin(user) {
  const settings = user?.settings && typeof user.settings === 'object' ? user.settings : {};
  const role = String(settings.role || settings.account_role || '').toLowerCase().replace(/[_-]+/g, ' ');
  const adminSetting = settings.admin;
  const adminEnabled = typeof adminSetting === 'object' && adminSetting !== null ? Boolean(adminSetting.enabled) : Boolean(adminSetting);

  return adminEnabled || Boolean(settings.is_admin) || ['admin', 'super admin', 'owner', 'moderator'].includes(role);
}

function openProfile(event, navigate, entity) {
  const path = profilePathFor(entity);
  if (!path) return;
  event?.preventDefault?.();
  event?.stopPropagation?.();
  navigate?.(path);
}

const LOGIN_RETURN_KEY = 'playhub_login_return_path';
const LOGIN_RETURN_TTL_MS = 30 * 60 * 1000;
const AUTH_RETURN_BLOCKED_PATHS = new Set(['/login', '/register', '/forgot-password']);

function safeAuthReturnPath(value) {
  if (typeof window === 'undefined') return '';
  try {
    const url = new URL(String(value || ''), window.location.origin);
    if (url.origin !== window.location.origin || !url.pathname.startsWith('/') || AUTH_RETURN_BLOCKED_PATHS.has(url.pathname)) return '';
    return `${url.pathname}${url.search}${url.hash}`;
  } catch (_) {
    return '';
  }
}

function currentAuthReturnPath() {
  if (typeof window === 'undefined') return '';
  return safeAuthReturnPath(`${window.location.pathname}${window.location.search}${window.location.hash}`);
}

function storeLoginReturnPath(path = currentAuthReturnPath()) {
  const safePath = safeAuthReturnPath(path);
  if (!safePath) return;
  try { localStorage.setItem(LOGIN_RETURN_KEY, JSON.stringify({ path: safePath, savedAt: Date.now() })); } catch (_) {}
}

function consumeLoginReturnPath() {
  if (typeof window === 'undefined') return '';
  try {
    const stored = JSON.parse(localStorage.getItem(LOGIN_RETURN_KEY) || '{}');
    localStorage.removeItem(LOGIN_RETURN_KEY);
    if (!stored?.path || Date.now() - Number(stored.savedAt || 0) > LOGIN_RETURN_TTL_MS) return '';
    return safeAuthReturnPath(stored.path);
  } catch (_) {
    try { localStorage.removeItem(LOGIN_RETURN_KEY); } catch (__) {}
    return '';
  }
}

function isLoginPath(value) {
  if (typeof window === 'undefined') return false;
  try { return new URL(String(value || ''), window.location.origin).pathname === '/login'; } catch (_) { return false; }
}

function loginSuccessRedirectPath() {
  return currentAuthReturnPath() || consumeLoginReturnPath() || '/';
}

function categoryIcon(name = '') {
  const icons = {
    documentary: 'explore',
    'travel & events': 'trending',
    technology: 'settings',
    education: 'studio',
    lifestyle: 'clock',
    music: 'mail',
    sports: 'like',
    gaming: 'play',
  };
  return icons[String(name).toLowerCase()] || 'explore';
}

function useRoute() {
  const [path, setPath] = useState(window.location.pathname);
  const [search, setSearch] = useState(window.location.search);
  const notifyNavigation = (source) => {
    const route = { path: window.location.pathname, search: window.location.search, hash: window.location.hash, source };
    window.dispatchEvent(new Event('playhub:navigation'));
    window.PlayHub?.doAction?.('playhub.route.changed', route);
  };
  const navigate = (to, options = {}) => {
    const filteredTarget = window.PlayHub?.applyFilters?.('playhub.navigation.target', to, { path: window.location.pathname, search: window.location.search }) ?? to;
    if (typeof filteredTarget !== 'string' || !filteredTarget) return;
    if (isLoginPath(filteredTarget)) storeLoginReturnPath();
    window.history[options.replace ? 'replaceState' : 'pushState']({}, '', filteredTarget);
    setPath(window.location.pathname);
    setSearch(window.location.search);
    notifyNavigation(options.source || 'navigate');
    if (!window.location.hash) window.scrollTo({ top: 0, behavior: 'smooth' });
  };
  useEffect(() => {
    const onPop = () => {
      setPath(window.location.pathname);
      setSearch(window.location.search);
      notifyNavigation('popstate');
    };
    const onPluginNavigate = (event) => navigate(event.detail?.to, { replace: Boolean(event.detail?.replace), source: 'plugin' });
    window.addEventListener('popstate', onPop);
    window.addEventListener('playhub:navigate-request', onPluginNavigate);
    return () => {
      window.removeEventListener('popstate', onPop);
      window.removeEventListener('playhub:navigate-request', onPluginNavigate);
    };
  }, []);
  return { path, search, navigate };
}

function scrollPaginationContentIntoView(source) {
  if (typeof window === 'undefined') return;
  window.setTimeout(() => {
    const container = source?.closest?.('.content-table-card, .live-browse-main, .studio-card, section, main');
    const target = container?.querySelector?.('.content-table-card, .content-table-wrap, .live-browse-grid') || container;
    target?.scrollIntoView?.({ behavior: 'smooth', block: 'start' });
  }, 80);
}

