      const requests = controlParticipants.filter((item) => !item.isLocal && item.cameraPublication && !item.cameraMuted).map((item) => sendParticipantAction({ action: 'mute_track', identity: item.identity, track_sid: item.cameraPublication.trackSid }));
      await Promise.all(requests);
