      await sendParticipantAction({ action: 'remove', identity: participant.identity, user_id: participant.userId });
      setControlParticipants((items) => items.filter((item) => item.identity !== participant.identity));
      setControlData((current) => ({ ...current, invites: current.invites.filter((invite) => Number(invite.user_id) !== Number(participant.userId)) }));
      setSelectedParticipant((identity) => identity === participant.identity ? (controlParticipants.find((item) => item.isLocal)?.identity || '') : identity);
      pushControlChatEvent({ identity: participant.identity, name: participant.name, type: 'participant_removed' });
      addControlActivity(`${participant.name} was removed from the stage.`);
      setNotice('Participant removed.');
