  const stepOneSubtitle = confirmationMethod === 'sms' ? 'Enter your phone number to receive a verification code.' : confirmationMethod === 'email' ? 'Enter your email to receive a verification code.' : stepOneIsPhone ? 'Enter your phone number to start registration.' : 'Enter your email to start registration.';
