  const googleImaClientRef = useRef(null);
  const googleImaRequestRef = useRef('');
  const playerAdResumeRef = useRef(false);
  const playerAdClickResumeRef = useRef(false);
  const playerAdBreaksRef = useRef(new Set());
  const playerAdBreakKeyRef = useRef('');
  const playerAdAfterBreakRef = useRef(null);
  const playerAdTrackingRef = useRef(new Set());
  const progressSyncRef = useRef({ slug: '', at: 0, time: 0 });
  const resumedRef = useRef(false);
  const autoplayAttemptedRef = useRef('');
  const defaultQualityAppliedRef = useRef(false);
  const detailMenuRef = useRef(null);
  const detailMenuShellRef = useRef(null);
  const playerContextMenuRef = useRef(null);
  const watchPlayerStageRef = useRef(null);
  const watchVideoPlayerRef = useRef(null);
