  useEffect(() => {
    if (!user?.id) return undefined;

    let cancelled = false;
    const refreshUserSettings = async () => {
      try {
        const data = await api.request('/auth/me');
        if (cancelled || !data.user) return;
        auth.setUser(data.user);
        if (!dirtyRef.current) {
          const refreshedForm = buildSettingsForm(data.user, themeRef.current, website);
          setForm(refreshedForm);
          setTwoFactorMethod(refreshedForm.twoFactorMethod || 'email');
          setTwoFactorContact(refreshedForm.twoFactorContact || '');
        }
      } catch (_) {
        // Keep the current form visible if a background refresh fails.
      }
    };
    const onVisible = () => {
      if (!document.hidden) refreshUserSettings();
    };

    window.addEventListener('focus', refreshUserSettings);
    document.addEventListener('visibilitychange', onVisible);
    const interval = window.setInterval(refreshUserSettings, 15000);

    return () => {
      cancelled = true;
      window.removeEventListener('focus', refreshUserSettings);
      document.removeEventListener('visibilitychange', onVisible);
      window.clearInterval(interval);
    };
  }, [user?.id]);

