  const updateSocial = (key, value) => { markDirty(); setForm((current) => ({ ...current, socials: { ...current.socials, [key]: value } })); };
  const insertSettingsBioEmoji = (emojiData) => {
    const emoji = emojiData?.emoji || '';
    if (!emoji) return;
    markDirty();
    setForm((current) => {
      const input = bioTextareaRef.current;
      const value = current.bio || '';
      const start = input?.selectionStart ?? value.length;
      const end = input?.selectionEnd ?? value.length;
      const nextBio = `${value.slice(0, start)}${emoji}${value.slice(end)}`.slice(0, 160);
      window.requestAnimationFrame(() => {
        const cursor = Math.min(start + emoji.length, nextBio.length);
        bioTextareaRef.current?.focus();
        bioTextareaRef.current?.setSelectionRange(cursor, cursor);
      });
      return { ...current, bio: nextBio };
    });
  };

