  const scheduleSettingsAutoSave = (nextForm) => {
    if (settingsAutoSaveTimerRef.current) window.clearTimeout(settingsAutoSaveTimerRef.current);
    const saveSeq = settingsAutoSaveSeqRef.current + 1;
    settingsAutoSaveSeqRef.current = saveSeq;
    settingsAutoSaveTimerRef.current = window.setTimeout(async () => {
      try {
        const response = await api.request('/auth/settings', {
          method: 'PUT',
          body: JSON.stringify(buildAutoSavePayload(nextForm)),
        });
        if (saveSeq === settingsAutoSaveSeqRef.current) {
          if (response.user) auth.setUser(response.user);
          setError('');
          showSettingsToast('Settings saved successfully.');
        }
      } catch (err) {
        const message = err.message || 'Unable to auto-save settings.';
        setError(message);
        showSettingsToast(message, 'error');
      }
    }, 0);
  };
